"""
    Determine the nth digit of an integer, starting at the right and counting
    from zero.

    >>> [_nth_digit(123, n) for n in range(5)]
    [3, 2, 1, 0, 0]

    """
def _nth_digit(i: Any, n: Any) -> object {
    return ((i // (10 ** n)) % 10);
}

